/**
 * SLA Manager — Computes deadlines and breach status for all tickets.
 * SLA definitions can be overridden via settings.
 */

export const DEFAULT_SLA_CONFIG = {
  urgent: { label: 'Urgent', hours: 2, color: '#ff4444', weight: 4 },
  high:   { label: 'High',   hours: 4, color: '#ff8c00', weight: 3 },
  normal: { label: 'Normal', hours: 24, color: '#4c9eff', weight: 2 },
  low:    { label: 'Low',    hours: 48, color: '#22c55e', weight: 1 },
};

let _slaConfig = { ...DEFAULT_SLA_CONFIG };

export function setSlaConfig(config) {
  _slaConfig = { ...DEFAULT_SLA_CONFIG, ...config };
}

export function getSlaConfig() {
  return _slaConfig;
}

/**
 * Compute the SLA deadline timestamp for a ticket.
 * @param {string} priority  — 'urgent' | 'high' | 'normal' | 'low'
 * @param {number} createdAt — Unix ms timestamp
 * @returns {number} deadline Unix ms timestamp
 */
export function computeDeadline(priority, createdAt) {
  const sla = _slaConfig[priority] ?? _slaConfig.normal;
  return createdAt + sla.hours * 60 * 60 * 1000;
}

/**
 * Returns milliseconds remaining until the SLA deadline.
 * Negative means overdue.
 */
export function timeRemaining(ticket, nowMs) {
  return ticket.slaDeadline - nowMs;
}

/**
 * Returns true if the ticket has breached its SLA deadline.
 */
export function isOverdue(ticket, nowMs) {
  if (['resolved', 'closed'].includes(ticket.status)) return false;
  return timeRemaining(ticket, nowMs) < 0;
}

/**
 * Returns a human-readable SLA status string.
 */
export function slaStatusLabel(ticket, nowMs) {
  if (['resolved', 'closed'].includes(ticket.status)) return 'Resolved';
  const ms = timeRemaining(ticket, nowMs);
  if (ms < 0) return 'OVERDUE';
  if (ms < 30 * 60 * 1000) return 'Critical';
  if (ms < 60 * 60 * 1000) return 'Imminent';
  if (ms < 4 * 60 * 60 * 1000) return 'Soon';
  return 'On Track';
}

/**
 * Maps slaStatusLabel → CSS class suffix for visual theming.
 */
export function slaStatusClass(ticket, nowMs) {
  const label = slaStatusLabel(ticket, nowMs);
  const map = {
    OVERDUE: 'overdue',
    Critical: 'critical',
    Imminent: 'imminent',
    Soon: 'soon',
    'On Track': 'on-track',
    Resolved: 'resolved',
  };
  return map[label] ?? 'on-track';
}

/**
 * Queue Engine — The heart of the system.
 *
 * ORDERING RULES (applied in strict precedence):
 *   Tier 1 — OVERDUE tickets (SLA breached) float to the absolute top,
 *             sorted by severity (most overdue → least overdue).
 *   Tier 2 — ACTIVE tickets sorted by time remaining to SLA deadline (nearest first).
 *             Tie-break: priority weight (urgent > high > normal > low).
 *             Second tie-break: creation timestamp (oldest FIFO).
 *   Tier 3 — RESOLVED / CLOSED tickets pushed to the bottom (sorted by resolvedAt desc).
 *
 * Resolved tickets are always last regardless of everything else.
 */

import { timeRemaining, isOverdue } from './slaManager.js';
import { getSlaConfig } from './slaManager.js';

const RESOLVED_STATUSES = new Set(['resolved', 'closed']);

function priorityWeight(ticket) {
  const config = getSlaConfig();
  return config[ticket.priority]?.weight ?? 0;
}

function isResolved(ticket) {
  return RESOLVED_STATUSES.has(ticket.status);
}

/**
 * Core comparator for sorting two tickets.
 * Returns negative if `a` should appear before `b`.
 */
export function compareTickets(a, b, nowMs) {
  const aResolved = isResolved(a);
  const bResolved = isResolved(b);

  // Tier 3: Push resolved tickets to the bottom
  if (aResolved && !bResolved) return 1;
  if (!aResolved && bResolved) return -1;
  if (aResolved && bResolved) {
    // Among resolved: sort by resolvedAt descending (most recent first)
    return (b.resolvedAt ?? 0) - (a.resolvedAt ?? 0);
  }

  const aOverdue = isOverdue(a, nowMs);
  const bOverdue = isOverdue(b, nowMs);

  // Tier 1: Overdue tickets always beat non-overdue
  if (aOverdue && !bOverdue) return -1;
  if (!aOverdue && bOverdue) return 1;

  // Both overdue: most severely overdue (lowest/most-negative timeRemaining) ranks higher
  if (aOverdue && bOverdue) {
    const diff = timeRemaining(a, nowMs) - timeRemaining(b, nowMs);
    if (diff !== 0) return diff; // more negative = more overdue = first
    return priorityWeight(b) - priorityWeight(a);
  }

  // Tier 2: Both active within SLA — nearest deadline first
  const remaining = timeRemaining(a, nowMs) - timeRemaining(b, nowMs);
  if (Math.abs(remaining) > 1000) return remaining; // > 1 second difference

  // Tie-break 1: Priority weight (higher weight = higher priority = first)
  const weightDiff = priorityWeight(b) - priorityWeight(a);
  if (weightDiff !== 0) return weightDiff;

  // Tie-break 2: FIFO — older ticket goes first
  return a.createdAt - b.createdAt;
}

/**
 * Returns a sorted copy of the given ticket array using the queue ordering rules.
 * @param {object[]} tickets
 * @param {number}   nowMs    — current time in milliseconds
 * @returns {object[]} sorted tickets
 */
export function sortQueue(tickets, nowMs) {
  return [...tickets].sort((a, b) => compareTickets(a, b, nowMs));
}

/**
 * Returns just the active (non-resolved) tickets, sorted by urgency.
 */
export function activeQueue(tickets, nowMs) {
  return sortQueue(
    tickets.filter(t => !isResolved(t)),
    nowMs
  );
}

/**
 * Returns the single most pressing ticket (first in sorted active queue).
 */
export function nextTicket(tickets, nowMs) {
  const sorted = activeQueue(tickets, nowMs);
  return sorted[0] ?? null;
}

/**
 * Time Simulator — Provides a real-time clock and an optional
 * time-warp offset so Priya (and evaluators) can watch tickets
 * breach their SLA deadline and leap to the front of the queue live.
 */

let _offset = 0; // ms added to real Date.now()
let _listeners = new Set();
let _tickInterval = null;

/**
 * Returns the current simulated time in milliseconds.
 */
export function now() {
  return Date.now() + _offset;
}

/**
 * Advance the simulated clock by `deltaMs` milliseconds.
 */
export function advanceTime(deltaMs) {
  _offset += deltaMs;
  _notifyListeners();
}

/**
 * Reset the simulated clock back to real time.
 */
export function resetTime() {
  _offset = 0;
  _notifyListeners();
}

/**
 * Returns the current time offset in milliseconds.
 */
export function getOffset() {
  return _offset;
}

/**
 * Subscribe to clock ticks (called every second).
 * @param {Function} fn — callback(nowMs)
 * @returns {Function} unsubscribe function
 */
export function subscribe(fn) {
  _listeners.add(fn);
  _ensureRunning();
  return () => {
    _listeners.delete(fn);
    if (_listeners.size === 0) _stopTicker();
  };
}

function _notifyListeners() {
  const t = now();
  _listeners.forEach(fn => fn(t));
}

function _ensureRunning() {
  if (_tickInterval !== null) return;
  _tickInterval = setInterval(() => {
    _notifyListeners();
  }, 1000);
}

function _stopTicker() {
  if (_tickInterval !== null) {
    clearInterval(_tickInterval);
    _tickInterval = null;
  }
}

/**
 * Format the current offset as a human-readable string for the UI.
 * e.g. "+2h 30m ahead", "Real time"
 */
export function formatOffset() {
  if (_offset === 0) return 'Real time';
  const sign = _offset > 0 ? '+' : '-';
  const abs = Math.abs(_offset);
  const h = Math.floor(abs / (3600 * 1000));
  const m = Math.floor((abs % (3600 * 1000)) / (60 * 1000));
  const parts = [];
  if (h) parts.push(`${h}h`);
  if (m) parts.push(`${m}m`);
  if (!parts.length) parts.push('<1m');
  return `${sign}${parts.join(' ')} ahead`;
}

/**
 * Formatters — Human-readable time and status display helpers.
 */

/**
 * Format milliseconds remaining into a countdown string.
 * Positive: "Due in 1h 22m"
 * Negative: "Overdue by 14m"
 * Zero:     "Due now"
 */
export function formatCountdown(ms) {
  if (ms === 0) return 'Due now';
  const abs = Math.abs(ms);
  const h = Math.floor(abs / (3600 * 1000));
  const m = Math.floor((abs % (3600 * 1000)) / (60 * 1000));
  const s = Math.floor((abs % (60 * 1000)) / 1000);

  const parts = [];
  if (h > 0) parts.push(`${h}h`);
  if (m > 0 || h > 0) parts.push(`${m}m`);
  if (h === 0) parts.push(`${s}s`);

  const timeStr = parts.join(' ');
  return ms < 0 ? `Overdue by ${timeStr}` : `Due in ${timeStr}`;
}

/**
 * Format a Unix ms timestamp to a locale date-time string.
 */
export function formatDateTime(ms) {
  if (!ms) return '—';
  return new Date(ms).toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true,
  });
}

/**
 * Format time ago (e.g. "3h ago", "just now")
 */
export function formatTimeAgo(ms) {
  const diff = Date.now() - ms;
  if (diff < 60_000) return 'just now';
  const m = Math.floor(diff / 60_000);
  const h = Math.floor(m / 60);
  const d = Math.floor(h / 24);
  if (d > 0) return `${d}d ago`;
  if (h > 0) return `${h}h ago`;
  return `${m}m ago`;
}

/**
 * Capitalize first letter of a string.
 */
export function capitalize(str) {
  if (!str) return '';
  return str.charAt(0).toUpperCase() + str.slice(1);
}

/**
 * Format status for display (e.g. 'in_progress' → 'In Progress')
 */
export function formatStatus(status) {
  return status
    .split('_')
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

/**
 * Helpers — Generic utility functions.
 */

let _idCounter = 1000;

/**
 * Generate a unique ticket ID like "TKT-1042"
 */
export function generateId() {
  return `TKT-${++_idCounter}`;
}

/**
 * Debounce a function — calls `fn` at most once per `delay` ms.
 */
export function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

/**
 * Clamp a number between min and max.
 */
export function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

/**
 * Deep clone a plain object (JSON-safe).
 */
export function clone(obj) {
  return JSON.parse(JSON.stringify(obj));
}

/**
 * Return a query-safe string for filtering
 */
export function normalizeSearch(str) {
  return (str ?? '').toLowerCase().trim();
}

/**
 * Create a DOM element with optional attributes and children.
 */
export function el(tag, attrs = {}, ...children) {
  const element = document.createElement(tag);
  for (const [key, val] of Object.entries(attrs)) {
    if (key === 'className') element.className = val;
    else if (key === 'innerHTML') element.innerHTML = val;
    else if (key.startsWith('on')) element.addEventListener(key.slice(2).toLowerCase(), val);
    else element.setAttribute(key, val);
  }
  for (const child of children) {
    if (child == null) continue;
    if (typeof child === 'string') element.appendChild(document.createTextNode(child));
    else element.appendChild(child);
  }
  return element;
}

/**
 * Select a single DOM element (shorthand).
 */
export function qs(selector, parent = document) {
  return parent.querySelector(selector);
}

/**
 * Select all matching DOM elements (shorthand).
 */
export function qsa(selector, parent = document) {
  return Array.from(parent.querySelectorAll(selector));
}

/**
 * Reactive Store — Central state management with LocalStorage persistence.
 * Provides a simple pub/sub model for reactive UI updates.
 */

import { seedTickets, TEAM } from './seed-data.js';
import { computeDeadline } from '../engine/slaManager.js';
import { generateId } from '../utils/helpers.js';

const STORAGE_KEY = 'helpdesk_tickets_v2';

// ── State shape ───────────────────────────────────────────────────────────────
let _state = {
  tickets: [],
  activeAgent: 'priya', // Current logged-in agent
  team: TEAM,
};

// ── Subscribers ───────────────────────────────────────────────────────────────
const _subscribers = new Set();

function _notify() {
  const snapshot = getState();
  _subscribers.forEach(fn => fn(snapshot));
}

export function subscribe(fn) {
  _subscribers.add(fn);
  return () => _subscribers.delete(fn);
}

// ── Initialization ────────────────────────────────────────────────────────────
export function init() {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored) {
    try {
      const parsed = JSON.parse(stored);
      _state.tickets = parsed;
      return;
    } catch {
      // fall through to seed
    }
  }
  _state.tickets = seedTickets;
  _persist();
}

function _persist() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(_state.tickets));
}

// ── Getters ───────────────────────────────────────────────────────────────────
export function getState() {
  return { ..._state };
}

export function getTickets() {
  return _state.tickets;
}

export function getTicketById(id) {
  return _state.tickets.find(t => t.id === id) ?? null;
}

export function getActiveAgent() {
  return _state.activeAgent;
}

export function getTeam() {
  return _state.team;
}

export function getAgentById(id) {
  return _state.team.find(a => a.id === id) ?? null;
}

// ── Mutations ─────────────────────────────────────────────────────────────────

export function setActiveAgent(agentId) {
  _state.activeAgent = agentId;
  _notify();
}

/**
 * Create a new ticket and add it to the store.
 */
export function createTicket({ customer, email, company, subject, priority, assignee }) {
  const createdAt = Date.now();
  const ticket = {
    id: generateId(),
    customer,
    email: email ?? '',
    company: company ?? '',
    subject,
    priority,
    status: 'open',
    assignee: assignee ?? null,
    createdAt,
    slaDeadline: computeDeadline(priority, createdAt),
    resolvedAt: null,
    note: null,
    history: [{ at: createdAt, msg: 'Ticket created' }],
  };
  _state.tickets = [ticket, ..._state.tickets];
  _persist();
  _notify();
  return ticket;
}

/**
 * Update specific fields on a ticket.
 */
export function updateTicket(id, changes) {
  _state.tickets = _state.tickets.map(t => {
    if (t.id !== id) return t;
    const updated = { ...t, ...changes };
    // Recompute SLA if priority changed
    if (changes.priority && changes.priority !== t.priority) {
      updated.slaDeadline = computeDeadline(updated.priority, updated.createdAt);
    }
    // Track status changes in history
    if (changes.status && changes.status !== t.status) {
      const entry = { at: Date.now(), msg: `Status changed to ${changes.status}` };
      updated.history = [...(t.history ?? []), entry];
      if (changes.status === 'resolved' || changes.status === 'closed') {
        updated.resolvedAt = Date.now();
      }
    }
    return updated;
  });
  _persist();
  _notify();
}

/**
 * Assign a ticket to an agent (or null to unassign).
 */
export function assignTicket(id, agentId) {
  updateTicket(id, { assignee: agentId });
}

/**
 * Delete a ticket permanently.
 */
export function deleteTicket(id) {
  _state.tickets = _state.tickets.filter(t => t.id !== id);
  _persist();
  _notify();
}

/**
 * Reset to seed data (for demo/testing).
 */
export function resetToSeed() {
  _state.tickets = seedTickets;
  _persist();
  _notify();
}

/* reset.css — Modern CSS Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img, picture, video, canvas, svg {
  display: block;
  max-width: 100%;
}

input, button, textarea, select {
  font: inherit;
}

p, h1, h2, h3, h4, h5, h6 {
  overflow-wrap: break-word;
}

button {
  cursor: pointer;
  border: none;
  background: none;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

table {
  border-collapse: collapse;
  border-spacing: 0;
}

/* variables.css — Design tokens & global theme */
:root {
  /* ── Brand Palette ──────────────────────────────────────────────── */
  --brand-primary:   #7c3aed;   /* Priya's deep violet */
  --brand-secondary: #0ea5e9;   /* Alex's sky blue */
  --brand-accent:    #f59e0b;   /* Warm amber accent */

  /* ── Dark Surface System ───────────────────────────────────────── */
  --bg-base:         #0a0b0f;   /* Page background — near black */
  --bg-surface:      #111318;   /* Cards, panels */
  --bg-elevated:     #1a1d25;   /* Modals, drawers, dropdowns */
  --bg-hover:        #20242f;   /* Row / item hover state */
  --bg-selected:     #1e1b3a;   /* Active selection */

  /* ── Glass Effect ──────────────────────────────────────────────── */
  --glass-bg:        rgba(26, 29, 37, 0.85);
  --glass-border:    rgba(255, 255, 255, 0.07);
  --glass-blur:      12px;

  /* ── Text ──────────────────────────────────────────────────────── */
  --text-primary:    #f0f2f8;
  --text-secondary:  #8b91a7;
  --text-muted:      #555b72;
  --text-inverse:    #0a0b0f;

  /* ── Border ────────────────────────────────────────────────────── */
  --border-subtle:   rgba(255, 255, 255, 0.06);
  --border-default:  rgba(255, 255, 255, 0.10);
  --border-strong:   rgba(255, 255, 255, 0.18);

  /* ── SLA / Priority Colors ─────────────────────────────────────── */
  --sla-overdue:     #ef4444;
  --sla-critical:    #f97316;
  --sla-imminent:    #eab308;
  --sla-soon:        #06b6d4;
  --sla-on-track:    #22c55e;
  --sla-resolved:    #6b7280;
  --sla-waiting:     #8b5cf6;

  --priority-urgent: #ef4444;
  --priority-high:   #f97316;
  --priority-normal: #3b82f6;
  --priority-low:    #22c55e;

  /* ── Status Colors ─────────────────────────────────────────────── */
  --status-open:        #3b82f6;
  --status-in-progress: #8b5cf6;
  --status-waiting:     #f59e0b;
  --status-resolved:    #22c55e;
  --status-closed:      #6b7280;

  /* ── Spacing ───────────────────────────────────────────────────── */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;

  /* ── Border Radius ─────────────────────────────────────────────── */
  --radius-sm:  6px;
  --radius-md:  10px;
  --radius-lg:  16px;
  --radius-xl:  24px;
  --radius-full: 9999px;

  /* ── Typography ────────────────────────────────────────────────── */
  --font-sans:  'Plus Jakarta Sans', system-ui, sans-serif;
  --font-mono:  'JetBrains Mono', 'Fira Code', monospace;

  --text-xs:   11px;
  --text-sm:   13px;
  --text-base: 15px;
  --text-md:   16px;
  --text-lg:   18px;
  --text-xl:   22px;
  --text-2xl:  28px;
  --text-3xl:  36px;

  /* ── Shadows ───────────────────────────────────────────────────── */
  --shadow-sm:  0 1px 3px rgba(0,0,0,0.4);
  --shadow-md:  0 4px 16px rgba(0,0,0,0.5);
  --shadow-lg:  0 8px 32px rgba(0,0,0,0.6);
  --shadow-glow-purple: 0 0 20px rgba(124, 58, 237, 0.4);
  --shadow-glow-red:    0 0 20px rgba(239, 68, 68, 0.4);
  --shadow-glow-amber:  0 0 16px rgba(245, 158, 11, 0.35);

  /* ── Transitions ───────────────────────────────────────────────── */
  --transition-fast:   0.12s ease;
  --transition-base:   0.2s ease;
  --transition-slow:   0.35s ease;

  /* ── Z-index layers ────────────────────────────────────────────── */
  --z-dropdown: 100;
  --z-drawer:   200;
  --z-modal:    300;
  --z-toast:    400;
}

/* ── Base Layout ───────────────────────────────────────────────────────────── */
body {
  background: var(--bg-base);
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: var(--text-base);
  min-height: 100vh;
  overflow-x: hidden;
}

.app-layout {
  display: grid;
  grid-template-rows: auto auto auto 1fr auto;
  min-height: 100vh;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 var(--space-6);
}

/* ── Scrollbar ─────────────────────────────────────────────────────────────── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.12); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.22); }

/* ── Utilities ─────────────────────────────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

.flex { display: flex; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: var(--space-2); }
.gap-3 { gap: var(--space-3); }
.gap-4 { gap: var(--space-4); }
.gap-6 { gap: var(--space-6); }
.flex-1 { flex: 1; }
.truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.font-mono { font-family: var(--font-mono); }
.text-sm { font-size: var(--text-sm); }
.text-xs { font-size: var(--text-xs); }
.text-muted { color: var(--text-secondary); }
.w-full { width: 100%; }

/* animations.css — Micro-animations for premium feel */

/* ── Queue row insertion / re-rank flash ──────────────────────────────── */
@keyframes rowSlideIn {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes flashOverdue {
  0%, 100% { background: transparent; }
  50%       { background: rgba(239, 68, 68, 0.08); }
}

@keyframes rankChange {
  0%   { background: rgba(124, 58, 237, 0.15); }
  100% { background: transparent; }
}

/* ── Pulse animations for live indicators ─────────────────────────────── */
@keyframes pulseDot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.5; transform: scale(0.85); }
}

@keyframes pulseGlowRed {
  0%, 100% { box-shadow: 0 0 6px rgba(239, 68, 68, 0.5); }
  50%       { box-shadow: 0 0 16px rgba(239, 68, 68, 0.9), 0 0 30px rgba(239, 68, 68, 0.4); }
}

@keyframes pulseGlowAmber {
  0%, 100% { box-shadow: 0 0 4px rgba(245, 158, 11, 0.4); }
  50%       { box-shadow: 0 0 12px rgba(245, 158, 11, 0.8); }
}

@keyframes spinSlow {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* ── Number badge bounce ──────────────────────────────────────────────── */
@keyframes badgePop {
  0%   { transform: scale(1); }
  40%  { transform: scale(1.35); }
  70%  { transform: scale(0.9); }
  100% { transform: scale(1); }
}

/* ── Slide in from right (drawer) ─────────────────────────────────────── */
@keyframes slideInRight {
  from { transform: translateX(100%); opacity: 0; }
  to   { transform: translateX(0);    opacity: 1; }
}

@keyframes slideOutRight {
  from { transform: translateX(0);    opacity: 1; }
  to   { transform: translateX(100%); opacity: 0; }
}

/* ── Fade + scale (modal) ─────────────────────────────────────────────── */
@keyframes fadeScaleIn {
  from { opacity: 0; transform: scale(0.94) translateY(8px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* ── Toast slide up ───────────────────────────────────────────────────── */
@keyframes toastIn {
  from { opacity: 0; transform: translateY(16px) scale(0.96); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes toastOut {
  from { opacity: 1; transform: translateY(0) scale(1); }
  to   { opacity: 0; transform: translateY(-8px) scale(0.96); }
}

/* ── Skeleton shimmer ─────────────────────────────────────────────────── */
@keyframes shimmer {
  from { background-position: -200% 0; }
  to   { background-position: 200% 0; }
}

/* ── Timer tick color flash ───────────────────────────────────────────── */
@keyframes timerTick {
  0%   { opacity: 1; }
  30%  { opacity: 0.6; }
  100% { opacity: 1; }
}

/* ── Application classes ──────────────────────────────────────────────── */
.animate-row-in     { animation: rowSlideIn 0.25s ease both; }
.animate-flash-red  { animation: flashOverdue 1.4s ease infinite; }
.animate-rank       { animation: rankChange 0.8s ease both; }
.animate-pulse-dot  { animation: pulseDot 1.5s ease-in-out infinite; }
.animate-glow-red   { animation: pulseGlowRed 2s ease-in-out infinite; }
.animate-glow-amber { animation: pulseGlowAmber 2s ease-in-out infinite; }
.animate-badge-pop  { animation: badgePop 0.35s ease both; }
.animate-timer      { animation: timerTick 1s ease-in-out; }

/* queue.css — Queue table, ticket rows, urgency badges, countdown timers */

/* ── Queue Wrapper ────────────────────────────────────────────────────────── */
.queue-wrapper {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

/* ── Table Header ─────────────────────────────────────────────────────────── */
.queue-table {
  width: 100%;
  table-layout: fixed;
}

.queue-table thead {
  background: rgba(255,255,255,0.03);
  border-bottom: 1px solid var(--border-subtle);
}

.queue-table th {
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-align: left;
  white-space: nowrap;
  user-select: none;
}

.queue-table th.col-rank    { width: 52px;  }
.queue-table th.col-id      { width: 100px; }
.queue-table th.col-subject { width: auto;  }
.queue-table th.col-customer{ width: 160px; }
.queue-table th.col-priority{ width: 90px;  }
.queue-table th.col-status  { width: 110px; }
.queue-table th.col-assignee{ width: 110px; }
.queue-table th.col-sla     { width: 160px; }
.queue-table th.col-actions { width: 80px;  text-align: right; }

/* ── Ticket Row ───────────────────────────────────────────────────────────── */
.ticket-row {
  border-bottom: 1px solid var(--border-subtle);
  transition: background var(--transition-fast);
  cursor: pointer;
  position: relative;
}

.ticket-row:last-child { border-bottom: none; }

.ticket-row:hover {
  background: var(--bg-hover);
}

.ticket-row.row--overdue {
  background: rgba(239, 68, 68, 0.04);
}
.ticket-row.row--overdue:hover {
  background: rgba(239, 68, 68, 0.08);
}

.ticket-row.row--critical {
  background: rgba(249, 115, 22, 0.03);
}

.ticket-row.row--resolved {
  opacity: 0.55;
}

.ticket-row.row--resolved:hover {
  opacity: 0.75;
  background: var(--bg-hover);
}

.ticket-row td {
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-sm);
  vertical-align: middle;
}

/* ── Rank Column ──────────────────────────────────────────────────────────── */
.rank-cell {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
  font-weight: 700;
  font-family: var(--font-mono);
  background: rgba(255,255,255,0.05);
  color: var(--text-muted);
  flex-shrink: 0;
}

.rank-cell.rank--top {
  background: rgba(124, 58, 237, 0.2);
  color: #a78bfa;
  border: 1px solid rgba(124, 58, 237, 0.35);
}

.rank-cell.rank--overdue {
  background: rgba(239, 68, 68, 0.15);
  color: #fca5a5;
  border: 1px solid rgba(239, 68, 68, 0.3);
  animation: pulseGlowRed 2s ease-in-out infinite;
}

/* ── Ticket ID ────────────────────────────────────────────────────────────── */
.ticket-id {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

/* ── Subject ──────────────────────────────────────────────────────────────── */
.ticket-subject {
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--text-primary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  line-height: 1.4;
  max-width: 100%;
}

.ticket-subject-wrap {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ticket-company {
  font-size: var(--text-xs);
  color: var(--text-muted);
}

/* ── Customer Cell ────────────────────────────────────────────────────────── */
.customer-cell {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.customer-name {
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.customer-company {
  font-size: var(--text-xs);
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Priority Badge ───────────────────────────────────────────────────────── */
.priority-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: 3px 8px;
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: 0.03em;
  white-space: nowrap;
}

.priority-badge::before {
  content: '';
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}

.priority-badge.priority--urgent {
  color: var(--priority-urgent);
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.25);
}

.priority-badge.priority--high {
  color: var(--priority-high);
  background: rgba(249, 115, 22, 0.12);
  border: 1px solid rgba(249, 115, 22, 0.25);
}

.priority-badge.priority--normal {
  color: var(--priority-normal);
  background: rgba(59, 130, 246, 0.12);
  border: 1px solid rgba(59, 130, 246, 0.25);
}

.priority-badge.priority--low {
  color: var(--priority-low);
  background: rgba(34, 197, 94, 0.10);
  border: 1px solid rgba(34, 197, 94, 0.22);
}

/* ── Status Badge ─────────────────────────────────────────────────────────── */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 500;
  white-space: nowrap;
}

.status-badge.status--open {
  color: var(--status-open);
  background: rgba(59, 130, 246, 0.10);
  border: 1px solid rgba(59, 130, 246, 0.22);
}

.status-badge.status--in_progress {
  color: #a78bfa;
  background: rgba(139, 92, 246, 0.10);
  border: 1px solid rgba(139, 92, 246, 0.22);
}

.status-badge.status--waiting {
  color: var(--status-waiting);
  background: rgba(245, 158, 11, 0.10);
  border: 1px solid rgba(245, 158, 11, 0.22);
}

.status-badge.status--resolved {
  color: var(--status-resolved);
  background: rgba(34, 197, 94, 0.08);
  border: 1px solid rgba(34, 197, 94, 0.18);
}

.status-badge.status--closed {
  color: var(--sla-resolved);
  background: rgba(107, 114, 128, 0.10);
  border: 1px solid rgba(107, 114, 128, 0.20);
}

/* ── Assignee Chip ────────────────────────────────────────────────────────── */
.assignee-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  max-width: 100%;
}

.agent-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 700;
  flex-shrink: 0;
}

.agent-name {
  font-size: var(--text-xs);
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.unassigned-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: var(--text-xs);
  color: var(--text-muted);
}

/* ── SLA Countdown Cell ───────────────────────────────────────────────────── */
.sla-cell {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sla-timer {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  font-weight: 600;
  white-space: nowrap;
}

.sla-timer.sla--overdue { color: var(--sla-overdue); }
.sla-timer.sla--critical { color: var(--sla-critical); }
.sla-timer.sla--imminent { color: var(--sla-imminent); }
.sla-timer.sla--soon { color: var(--sla-soon); }
.sla-timer.sla--on-track { color: var(--sla-on-track); }
.sla-timer.sla--resolved { color: var(--sla-resolved); }
.sla-timer.sla--waiting { color: var(--sla-waiting); }

.sla-bar-track {
  height: 3px;
  border-radius: var(--radius-full);
  background: rgba(255,255,255,0.06);
  overflow: hidden;
  width: 100%;
}

.sla-bar-fill {
  height: 100%;
  border-radius: var(--radius-full);
  transition: width 1s linear;
}

.sla-bar-fill.sla--overdue  { background: var(--sla-overdue); }
.sla-bar-fill.sla--critical { background: var(--sla-critical); }
.sla-bar-fill.sla--imminent { background: var(--sla-imminent); }
.sla-bar-fill.sla--soon     { background: var(--sla-soon); }
.sla-bar-fill.sla--on-track { background: var(--sla-on-track); }
.sla-bar-fill.sla--resolved { background: var(--sla-resolved); }
.sla-bar-fill.sla--waiting  { background: var(--sla-waiting); }

/* ── Actions Cell ─────────────────────────────────────────────────────────── */
.actions-cell {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--space-1);
}

.action-btn {
  width: 30px;
  height: 30px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: all var(--transition-fast);
  background: transparent;
}

.action-btn:hover {
  background: var(--bg-elevated);
  color: var(--text-primary);
}

.action-btn.action--assign:hover { color: #7c3aed; }
.action-btn.action--view:hover   { color: #0ea5e9; }
.action-btn.action--resolve:hover { color: #22c55e; }

/* ── Empty State ──────────────────────────────────────────────────────────── */
.queue-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--space-16) var(--space-8);
  gap: var(--space-4);
  color: var(--text-muted);
  text-align: center;
}

.queue-empty-icon {
  font-size: 48px;
  opacity: 0.4;
}

.queue-empty-title {
  font-size: var(--text-lg);
  font-weight: 600;
  color: var(--text-secondary);
}

.queue-empty-subtitle {
  font-size: var(--text-sm);
  max-width: 280px;
  line-height: 1.6;
}

/* components.css — Header, stats, filters, modals, drawers, pagination, toasts */

/* ════════════════════════════════════════════════════════════════════════════
   APP HEADER
   ════════════════════════════════════════════════════════════════════════════ */
.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-5) 0;
  border-bottom: 1px solid var(--border-subtle);
}

.header-brand {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.brand-logo {
  width: 36px;
  height: 36px;
  background: linear-gradient(135deg, #7c3aed, #0ea5e9);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  flex-shrink: 0;
  box-shadow: var(--shadow-glow-purple);
}

.brand-title {
  font-size: var(--text-lg);
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.brand-subtitle {
  font-size: var(--text-xs);
  color: var(--text-muted);
  font-weight: 400;
}

.header-right {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

/* ── Live Clock ─────────────────────────────────────────────────────── */
.live-clock {
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  color: var(--text-muted);
}

.live-clock .clock-time {
  color: var(--text-secondary);
  font-weight: 500;
}

/* ── Agent Switcher ─────────────────────────────────────────────────── */
.agent-switcher {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-full);
  padding: var(--space-1) var(--space-2);
}

.agent-switcher-btn {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--text-muted);
  transition: all var(--transition-fast);
}

.agent-switcher-btn:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.agent-switcher-btn.active {
  background: var(--bg-selected);
  color: var(--text-primary);
}

.agent-switcher-btn.active .agent-avatar {
  box-shadow: 0 0 0 2px var(--border-strong);
}

/* ── Header Buttons ─────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-md);
  font-size: var(--text-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
  cursor: pointer;
}

.btn--primary {
  background: linear-gradient(135deg, #7c3aed, #6d28d9);
  color: white;
  border: 1px solid rgba(124, 58, 237, 0.4);
  box-shadow: 0 2px 8px rgba(124, 58, 237, 0.3);
}

.btn--primary:hover {
  background: linear-gradient(135deg, #8b5cf6, #7c3aed);
  box-shadow: 0 4px 16px rgba(124, 58, 237, 0.5);
  transform: translateY(-1px);
}

.btn--primary:active {
  transform: translateY(0);
}

.btn--ghost {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-default);
}

.btn--ghost:hover {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border-color: var(--border-strong);
}

.btn--danger {
  background: rgba(239, 68, 68, 0.1);
  color: var(--sla-overdue);
  border: 1px solid rgba(239, 68, 68, 0.25);
}

.btn--danger:hover {
  background: rgba(239, 68, 68, 0.2);
  box-shadow: 0 2px 12px rgba(239, 68, 68, 0.25);
}

.btn--sm {
  padding: var(--space-1) var(--space-3);
  font-size: var(--text-xs);
  border-radius: var(--radius-sm);
}

/* ════════════════════════════════════════════════════════════════════════════
   STATS BANNER
   ════════════════════════════════════════════════════════════════════════════ */
.stats-banner {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
  padding: var(--space-5) 0;
}

.stat-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--space-4) var(--space-5);
  display: flex;
  align-items: center;
  gap: var(--space-4);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.stat-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
}

.stat-card.stat--overdue::before { background: var(--sla-overdue); }
.stat-card.stat--urgent::before  { background: var(--sla-critical); }
.stat-card.stat--active::before  { background: var(--brand-primary); }
.stat-card.stat--resolved::before { background: var(--sla-on-track); }

.stat-card:hover {
  border-color: var(--border-default);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.stat-icon {
  font-size: 24px;
  flex-shrink: 0;
}

.stat-content {
  flex: 1;
  min-width: 0;
}

.stat-value {
  font-size: var(--text-2xl);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  letter-spacing: -0.03em;
}

.stat-card.stat--overdue .stat-value { color: var(--sla-overdue); }
.stat-card.stat--urgent  .stat-value { color: var(--sla-critical); }
.stat-card.stat--active  .stat-value { color: var(--brand-primary); }
.stat-card.stat--resolved .stat-value { color: var(--sla-on-track); }

.stat-label {
  font-size: var(--text-xs);
  color: var(--text-muted);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-top: 2px;
}

.stat-badge-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.stat-card.stat--overdue .stat-badge-pulse {
  background: var(--sla-overdue);
  animation: pulseDot 1.2s ease-in-out infinite;
}

/* ════════════════════════════════════════════════════════════════════════════
   PICK NEXT BANNER
   ════════════════════════════════════════════════════════════════════════════ */
.pick-next-banner {
  background: linear-gradient(135deg, rgba(124,58,237,0.12), rgba(14,165,233,0.08));
  border: 1px solid rgba(124, 58, 237, 0.25);
  border-radius: var(--radius-lg);
  padding: var(--space-5) var(--space-6);
  display: flex;
  align-items: center;
  gap: var(--space-5);
  margin: var(--space-4) 0;
  position: relative;
  overflow: hidden;
}

.pick-next-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 60%, rgba(124,58,237,0.05));
  pointer-events: none;
}

.pick-next-rank {
  font-size: var(--text-3xl);
  font-weight: 900;
  color: rgba(124,58,237,0.3);
  font-family: var(--font-mono);
  flex-shrink: 0;
  line-height: 1;
}

.pick-next-content {
  flex: 1;
  min-width: 0;
}

.pick-next-label {
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #a78bfa;
  margin-bottom: var(--space-1);
}

.pick-next-subject {
  font-size: var(--text-md);
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.3;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 1;
  line-clamp: 1;
  -webkit-box-orient: vertical;
}

.pick-next-meta {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin-top: var(--space-2);
  font-size: var(--text-xs);
  color: var(--text-muted);
}

.pick-next-actions {
  display: flex;
  gap: var(--space-2);
  flex-shrink: 0;
}

/* ════════════════════════════════════════════════════════════════════════════
   TIME SIMULATOR BAR
   ════════════════════════════════════════════════════════════════════════════ */
.sim-bar {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  background: rgba(245, 158, 11, 0.07);
  border: 1px solid rgba(245, 158, 11, 0.18);
  border-radius: var(--radius-md);
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-xs);
  margin: var(--space-3) 0;
}

.sim-bar-label {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--brand-accent);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.sim-offset {
  font-family: var(--font-mono);
  color: var(--text-secondary);
  font-weight: 500;
  background: rgba(255,255,255,0.06);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
