/**
 * queueHeader.js — Live stats banner: Overdue, Approaching, Active, Resolved.
 */

import { isOverdue, timeRemaining } from '../engine/slaManager.js';
import { now } from '../engine/timeSimulator.js';

export function renderQueueHeader(tickets, container) {
  const t = now();
  const active = tickets.filter(tk => !['resolved', 'closed'].includes(tk.status));
  const overdue = active.filter(tk => isOverdue(tk, t));
  const approaching = active.filter(tk => {
    const rem = timeRemaining(tk, t);
    return rem >= 0 && rem < 60 * 60 * 1000; // within 1 hour
  });
  const resolved = tickets.filter(tk => tk.status === 'resolved' || tk.status === 'closed');

  container.innerHTML = `
    <div class="stats-banner">
      <div class="stat-card stat--overdue" id="stat-overdue">
        <span class="stat-icon">🔴</span>
        <div class="stat-content">
          <div class="stat-value" id="stat-overdue-count">${overdue.length}</div>
          <div class="stat-label">Overdue</div>
        </div>
        ${overdue.length > 0 ? '<span class="stat-badge-pulse"></span>' : ''}
      </div>
      <div class="stat-card stat--urgent" id="stat-approaching">
        <span class="stat-icon">⚡</span>
        <div class="stat-content">
          <div class="stat-value" id="stat-approaching-count">${approaching.length}</div>
          <div class="stat-label">Due &lt; 1h</div>
        </div>
      </div>
      <div class="stat-card stat--active" id="stat-active">
        <span class="stat-icon">📋</span>
        <div class="stat-content">
          <div class="stat-value" id="stat-active-count">${active.length}</div>
          <div class="stat-label">Active Tickets</div>
        </div>
      </div>
      <div class="stat-card stat--resolved" id="stat-resolved">
        <span class="stat-icon">✅</span>
        <div class="stat-content">
          <div class="stat-value" id="stat-resolved-count">${resolved.length}</div>
          <div class="stat-label">Resolved Today</div>
        </div>
      </div>
    </div>
  `;
}

export function updateQueueHeader(tickets) {
  const t = now();
  const active = tickets.filter(tk => !['resolved', 'closed'].includes(tk.status));
  const overdue = active.filter(tk => isOverdue(tk, t));
  const approaching = active.filter(tk => {
    const rem = timeRemaining(tk, t);
    return rem >= 0 && rem < 60 * 60 * 1000;
  });
  const resolved = tickets.filter(tk => tk.status === 'resolved' || tk.status === 'closed');

  const prevOverdue = parseInt(document.getElementById('stat-overdue-count')?.textContent ?? '0');

  document.getElementById('stat-overdue-count') && (document.getElementById('stat-overdue-count').textContent = overdue.length);
  document.getElementById('stat-approaching-count') && (document.getElementById('stat-approaching-count').textContent = approaching.length);
  document.getElementById('stat-active-count') && (document.getElementById('stat-active-count').textContent = active.length);
  document.getElementById('stat-resolved-count') && (document.getElementById('stat-resolved-count').textContent = resolved.length);

  // Animate badge pop if overdue count changed
  if (overdue.length !== prevOverdue) {
    const el = document.getElementById('stat-overdue-count');
    if (el) {
      el.classList.remove('animate-badge-pop');
      void el.offsetWidth;
      el.classList.add('animate-badge-pop');
    }
  }
}

/**
 * pickNextBanner.js — Hero callout showing the #1 most pressing ticket.
 */

import { nextTicket } from '../engine/queueEngine.js';
import { slaStatusClass, timeRemaining } from '../engine/slaManager.js';
import { now } from '../engine/timeSimulator.js';
import { formatCountdown } from '../utils/formatters.js';
import { getTeam } from '../state/store.js';

export function renderPickNextBanner(tickets, container, { onPick, onView }) {
  const t = now();
  const top = nextTicket(tickets, t);

  if (!top) {
    container.innerHTML = `
      <div class="pick-next-banner" style="opacity:0.5; justify-content:center;">
        <span style="font-size:20px;">🎉</span>
        <span style="font-size:14px; color:var(--text-secondary);">Queue is clear — great work!</span>
      </div>
    `;
    return;
  }

  const statusClass = slaStatusClass(top, t);
  const remaining = timeRemaining(top, t);
  const countdown = formatCountdown(remaining);
  const team = getTeam();
  const agent = team.find(a => a.id === top.assignee);

  const isOverdueTicket = remaining < 0;

  container.innerHTML = `
    <div class="pick-next-banner ${isOverdueTicket ? 'animate-flash-red' : ''}" style="${isOverdueTicket ? 'border-color: rgba(239,68,68,0.4);' : ''}">
      <div class="pick-next-rank">#1</div>
      <div class="pick-next-content">
        <div class="pick-next-label">
          ${isOverdueTicket ? '🚨 OVERDUE — Pick this ticket now' : '⚡ Next Most Pressing Ticket'}
        </div>
        <div class="pick-next-subject">${escHtml(top.subject)}</div>
        <div class="pick-next-meta">
          <span class="font-mono sla-timer sla--${statusClass}" id="pick-next-timer">${countdown}</span>
          <span>·</span>
          <span>${escHtml(top.customer)}</span>
          <span>·</span>
          <span class="priority-badge priority--${top.priority}">${cap(top.priority)}</span>
          ${agent ? `<span>·</span><span>${agent.name}</span>` : '<span>· Unassigned</span>'}
        </div>
      </div>
      <div class="pick-next-actions">
        <button class="btn btn--ghost btn--sm" id="pick-next-view-btn">View</button>
        <button class="btn btn--primary btn--sm" id="pick-next-btn">
          ${top.assignee ? '▶ Resume' : '▶ Pick & Assign'}
        </button>
      </div>
    </div>
  `;

  document.getElementById('pick-next-btn')?.addEventListener('click', (e) => {
    e.stopPropagation();
    onPick(top);
  });
  document.getElementById('pick-next-view-btn')?.addEventListener('click', (e) => {
    e.stopPropagation();
    onView(top);
  });
}

export function updatePickNextTimer(tickets) {
  const t = now();
  const top = nextTicket(tickets, t);
  const el = document.getElementById('pick-next-timer');
  if (!el || !top) return;
  const remaining = timeRemaining(top, t);
  const statusClass = slaStatusClass(top, t);
  el.textContent = formatCountdown(remaining);
  el.className = `font-mono sla-timer sla--${statusClass}`;
}

function escHtml(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function cap(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

/**
 * filterBar.js — Quick filter pills, search input, and dropdowns.
 * Manages filter state and notifies parent via onChange callback.
 */

import { debounce } from '../utils/helpers.js';
import { isOverdue } from '../engine/slaManager.js';
import { now } from '../engine/timeSimulator.js';
import { getTeam } from '../state/store.js';

const FILTERS = {
  search: '',
  tab: 'all',       // 'all' | 'overdue' | 'mine' | 'unassigned'
  priority: 'all',  // 'all' | 'urgent' | 'high' | 'normal' | 'low'
  status: 'active', // 'active' | 'all' | 'open' | 'in_progress' | 'waiting' | 'resolved'
};

let _filters = { ...FILTERS };
let _onChange = null;

export function getFilters() { return { ..._filters }; }

export function renderFilterBar(container, { onChange, activeAgentId, allTickets }) {
  _onChange = onChange;
  const t = now();
  const team = getTeam();

  const overdueCount = allTickets.filter(tk =>
    !['resolved', 'closed'].includes(tk.status) && isOverdue(tk, t)
  ).length;

  const mineCount = allTickets.filter(tk =>
    !['resolved', 'closed'].includes(tk.status) && tk.assignee === activeAgentId
  ).length;

  const unassignedCount = allTickets.filter(tk =>
    !['resolved', 'closed'].includes(tk.status) && !tk.assignee
  ).length;

  const activeAgent = team.find(a => a.id === activeAgentId);

  container.innerHTML = `
    <div class="filter-bar">
      <div class="search-wrap">
        <span class="search-icon">🔍</span>
        <input
          type="text"
          id="search-input"
          class="search-input"
          placeholder="Search by customer, subject, ID…"
          value="${escHtml(_filters.search)}"
          autocomplete="off"
        />
        <span class="search-clear" id="search-clear" title="Clear search">✕</span>
      </div>

      <div class="filter-pills">
        <button class="filter-pill ${_filters.tab === 'all' ? 'active' : ''}" data-tab="all" id="pill-all">
          All Tickets
          <span class="pill-count">${allTickets.filter(t2 => !['resolved','closed'].includes(t2.status)).length}</span>
        </button>

        <button class="filter-pill pill--overdue ${_filters.tab === 'overdue' ? 'active' : ''}" data-tab="overdue" id="pill-overdue">
          🔴 Overdue
          <span class="pill-count">${overdueCount}</span>
        </button>

        <button class="filter-pill pill--my-tickets ${_filters.tab === 'mine' ? 'active' : ''}" data-tab="mine" id="pill-mine">
          👤 ${activeAgent?.name ?? 'My Tickets'}
          <span class="pill-count">${mineCount}</span>
        </button>

        <button class="filter-pill pill--unassigned ${_filters.tab === 'unassigned' ? 'active' : ''}" data-tab="unassigned" id="pill-unassigned">
          ○ Unassigned
          <span class="pill-count">${unassignedCount}</span>
        </button>
      </div>

      <div style="display:flex; gap:8px; margin-left:auto;">
        <select class="filter-select" id="priority-filter">
          <option value="all" ${_filters.priority === 'all' ? 'selected' : ''}>All Priorities</option>
          <option value="urgent" ${_filters.priority === 'urgent' ? 'selected' : ''}>🔴 Urgent</option>
          <option value="high"   ${_filters.priority === 'high'   ? 'selected' : ''}>🟠 High</option>
          <option value="normal" ${_filters.priority === 'normal' ? 'selected' : ''}>🔵 Normal</option>
          <option value="low"    ${_filters.priority === 'low'    ? 'selected' : ''}>🟢 Low</option>
        </select>

        <select class="filter-select" id="status-filter">
          <option value="active" ${_filters.status === 'active' ? 'selected' : ''}>Active</option>
          <option value="all"    ${_filters.status === 'all' ? 'selected' : ''}>All Status</option>
          <option value="open"         ${_filters.status === 'open' ? 'selected' : ''}>Open</option>
          <option value="in_progress"  ${_filters.status === 'in_progress' ? 'selected' : ''}>In Progress</option>
          <option value="waiting"      ${_filters.status === 'waiting' ? 'selected' : ''}>Waiting</option>
          <option value="resolved"     ${_filters.status === 'resolved' ? 'selected' : ''}>Resolved</option>
        </select>
      </div>
    </div>
  `;

  // Bind events
  const searchInput = document.getElementById('search-input');
  const searchClear = document.getElementById('search-clear');

  const debouncedSearch = debounce((val) => {
    _filters.search = val;
    _onChange?.(_filters);
  }, 250);

  searchInput?.addEventListener('input', e => {
    debouncedSearch(e.target.value.trim());
  });

  searchClear?.addEventListener('click', () => {
    _filters.search = '';
    searchInput.value = '';
    _onChange?.(_filters);
  });

  container.querySelectorAll('[data-tab]').forEach(btn => {
    btn.addEventListener('click', () => {
      _filters.tab = btn.dataset.tab;
      renderFilterBar(container, { onChange, activeAgentId, allTickets });
      _onChange?.(_filters);
    });
  });

  document.getElementById('priority-filter')?.addEventListener('change', e => {
    _filters.priority = e.target.value;
    _onChange?.(_filters);
  });

  document.getElementById('status-filter')?.addEventListener('change', e => {
    _filters.status = e.target.value;
    _onChange?.(_filters);
  });
}

/**
 * Apply filter state to a sorted ticket list.
 */
export function applyFilters(sortedTickets, filters, activeAgentId) {
  const { search, tab, priority, status } = filters;
  const t = now();

  return sortedTickets.filter(ticket => {
    // Status filter
    if (status === 'active') {
      if (['resolved', 'closed'].includes(ticket.status)) return false;
    } else if (status !== 'all') {
      if (ticket.status !== status) return false;
    }

    // Tab filter
    if (tab === 'overdue' && !isOverdue(ticket, t)) return false;
    if (tab === 'mine' && ticket.assignee !== activeAgentId) return false;
    if (tab === 'unassigned' && ticket.assignee !== null) return false;

    // Priority filter
    if (priority !== 'all' && ticket.priority !== priority) return false;

    // Search
    if (search) {
      const q = search.toLowerCase();
      const searchable = [
        ticket.id,
        ticket.customer,
        ticket.company,
        ticket.subject,
        ticket.email,
      ].join(' ').toLowerCase();
      if (!searchable.includes(q)) return false;
    }

    return true;
  });
}

function escHtml(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/**
 * pagination.js — Pagination controls with per-page selector and keyboard nav.
 */

let _page = 1;
let _perPage = 15;

export function getPage() { return _page; }
export function getPerPage() { return _perPage; }
export function setPage(p) { _page = p; }

export function paginateTickets(tickets) {
  const start = (_page - 1) * _perPage;
  const end = start + _perPage;
  return tickets.slice(start, end);
}

export function totalPages(ticketCount) {
  return Math.max(1, Math.ceil(ticketCount / _perPage));
}

export function renderPagination(container, { total, onChange }) {
  const pages = totalPages(total);
  const safeCurrentPage = Math.min(_page, pages);
  if (safeCurrentPage !== _page) { _page = safeCurrentPage; }

  const start = (_page - 1) * _perPage + 1;
  const end = Math.min(_page * _perPage, total);

  // Build page buttons (show at most 7 buttons with ellipsis)
  const pageButtons = buildPageButtons(_page, pages);

  container.innerHTML = `
    <div class="pagination">
      <div class="pagination-info">
        ${total === 0 ? 'No tickets' : `Showing <strong>${start}–${end}</strong> of <strong>${total}</strong>`}
      </div>
      <div class="pagination-controls">
        <button class="page-btn" id="page-prev" aria-label="Previous page" ${_page <= 1 ? 'disabled' : ''}>‹</button>
        ${pageButtons}
        <button class="page-btn" id="page-next" aria-label="Next page" ${_page >= pages ? 'disabled' : ''}>›</button>
        <select class="per-page-select" id="per-page-select" title="Rows per page">
          ${[10, 15, 25, 50].map(n =>
            `<option value="${n}" ${_perPage === n ? 'selected' : ''}>${n} / page</option>`
          ).join('')}
        </select>
      </div>
    </div>
  `;

  document.getElementById('page-prev')?.addEventListener('click', () => {
    if (_page > 1) { _page--; onChange(); }
  });

  document.getElementById('page-next')?.addEventListener('click', () => {
    if (_page < pages) { _page++; onChange(); }
  });

  container.querySelectorAll('.page-btn[data-page]').forEach(btn => {
    btn.addEventListener('click', () => {
      _page = parseInt(btn.dataset.page);
      onChange();
    });
  });

  document.getElementById('per-page-select')?.addEventListener('change', e => {
    _perPage = parseInt(e.target.value);
    _page = 1;
    onChange();
  });
}

function buildPageButtons(current, total) {
  if (total <= 7) {
    return range(1, total + 1).map(p => pageBtn(p, current)).join('');
  }

  const buttons = [];
  buttons.push(pageBtn(1, current));

  if (current > 4) buttons.push('<span class="page-dots">…</span>');

  const lo = Math.max(2, current - 2);
  const hi = Math.min(total - 1, current + 2);

  for (let p = lo; p <= hi; p++) {
    buttons.push(pageBtn(p, current));
  }

  if (current < total - 3) buttons.push('<span class="page-dots">…</span>');
  buttons.push(pageBtn(total, current));

  return buttons.join('');
}

function pageBtn(p, current) {
  return `<button class="page-btn ${p === current ? 'active' : ''}" data-page="${p}">${p}</button>`;
}

function range(start, end) {
  return Array.from({ length: end - start }, (_, i) => start + i);
}

/**
 * ticketList.js — Renders the main ticket queue table with live SLA timers.
 */

import { slaStatusClass, timeRemaining, isOverdue } from '../engine/slaManager.js';
import { getSlaConfig } from '../engine/slaManager.js';
import { now } from '../engine/timeSimulator.js';
import { formatCountdown, formatDateTime, formatStatus } from '../utils/formatters.js';
import { getTeam } from '../state/store.js';

export function renderTicketList(tickets, container, { onView, onAssign, onResolve, onStatusChange }) {
  const team = getTeam();

  if (tickets.length === 0) {
    container.innerHTML = `
      <div class="queue-empty">
        <div class="queue-empty-icon">🗂️</div>
        <div class="queue-empty-title">No tickets match</div>
        <div class="queue-empty-subtitle">Try adjusting your filters or search query</div>
      </div>
    `;
    return;
  }

  const t = now();

  const rows = tickets.map((ticket, idx) => renderRow(ticket, idx, t, team, { onView, onAssign, onResolve, onStatusChange }));

  container.innerHTML = `
    <table class="queue-table" aria-label="Helpdesk ticket queue">
      <thead>
        <tr>
          <th class="col-rank">#</th>
          <th class="col-id">ID</th>
          <th class="col-subject">Subject</th>
          <th class="col-customer">Customer</th>
          <th class="col-priority">Priority</th>
          <th class="col-status">Status</th>
          <th class="col-assignee">Assignee</th>
          <th class="col-sla">SLA / Deadline</th>
          <th class="col-actions">Actions</th>
        </tr>
      </thead>
      <tbody id="ticket-tbody">
        ${rows.join('')}
      </tbody>
    </table>
  `;

  // Bind click events
  container.querySelectorAll('.ticket-row').forEach(row => {
    row.addEventListener('click', (e) => {
      if (e.target.closest('.action-btn')) return;
      const id = row.dataset.id;
      const ticket = tickets.find(t2 => t2.id === id);
      if (ticket) onView(ticket);
    });
  });

  container.querySelectorAll('.action--view').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const id = btn.dataset.id;
      const ticket = tickets.find(t2 => t2.id === id);
      if (ticket) onView(ticket);
    });
  });

  container.querySelectorAll('.action--assign').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const id = btn.dataset.id;
      const ticket = tickets.find(t2 => t2.id === id);
      if (ticket) onAssign(ticket);
    });
  });

  container.querySelectorAll('.action--resolve').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const id = btn.dataset.id;
      const ticket = tickets.find(t2 => t2.id === id);
      if (ticket) onResolve(ticket);
    });
  });
}

/**
 * Update only the SLA timer cells (called every second).
 */
export function updateTicketTimers(tickets) {
  const t = now();
  tickets.forEach(ticket => {
    const timerEl = document.getElementById(`sla-timer-${ticket.id}`);
    const barEl = document.getElementById(`sla-bar-${ticket.id}`);
    if (!timerEl) return;

    const statusClass = slaStatusClass(ticket, t);
    const remaining = timeRemaining(ticket, t);
    const isRes = ['resolved', 'closed'].includes(ticket.status);

    if (isRes) {
      timerEl.textContent = 'Resolved';
      timerEl.className = `sla-timer sla--resolved`;
      return;
    }

    timerEl.textContent = formatCountdown(remaining);
    timerEl.className = `sla-timer sla--${statusClass}`;

    if (barEl) {
      const config = getSlaConfig();
      const slaHours = config[ticket.priority]?.hours ?? 24;
      const totalMs = slaHours * 3600 * 1000;
      const elapsed = ticket.slaDeadline - ticket.createdAt - Math.max(remaining, 0);
      const pct = Math.min(100, Math.max(0, (elapsed / totalMs) * 100));
      barEl.style.width = `${pct}%`;
      barEl.className = `sla-bar-fill sla--${statusClass}`;
    }

    // If ticket just became overdue, update the row class
    const row = document.querySelector(`.ticket-row[data-id="${ticket.id}"]`);
    if (row && remaining < 0) {
      row.classList.add('row--overdue');
      row.classList.remove('row--critical');
    } else if (row && remaining < 30 * 60 * 1000) {
      row.classList.add('row--critical');
    }
  });
}

function renderRow(ticket, idx, t, team, handlers) {
  const statusClass = slaStatusClass(ticket, t);
  const remaining = timeRemaining(ticket, t);
  const overdue = isOverdue(ticket, t);
  const isResolved = ['resolved', 'closed'].includes(ticket.status);

  const agent = team.find(a => a.id === ticket.assignee);

  // SLA bar percentage
  const config = getSlaConfig();
  const slaHours = config[ticket.priority]?.hours ?? 24;
  const totalMs = slaHours * 3600 * 1000;
  const elapsed = isResolved ? totalMs : (ticket.slaDeadline - ticket.createdAt - Math.max(remaining, 0));
  const barPct = isResolved ? 100 : Math.min(100, Math.max(0, (elapsed / totalMs) * 100));

  const rowClass = [
    'ticket-row',
    overdue ? 'row--overdue' : '',
    !overdue && remaining < 30 * 60 * 1000 && !isResolved ? 'row--critical' : '',
    isResolved ? 'row--resolved' : '',
    'animate-row-in',
  ].filter(Boolean).join(' ');

  const rankClass = idx === 0 && !isResolved ? 'rank-cell rank--top' : overdue ? 'rank-cell rank--overdue' : 'rank-cell';

  const agentHtml = agent
    ? `<div class="assignee-chip">
         <div class="agent-avatar" style="background:${agent.color}20; color:${agent.color};">${agent.avatar}</div>
         <span class="agent-name">${escHtml(agent.name.split(' ')[0])}</span>
       </div>`
    : `<span class="unassigned-chip">○ Unassigned</span>`;

  const actionsHtml = isResolved
    ? `<div class="actions-cell">
         <button class="action-btn action--view" data-id="${ticket.id}" title="View">👁</button>
       </div>`
    : `<div class="actions-cell">
         <button class="action-btn action--view" data-id="${ticket.id}" title="View details">👁</button>
         <button class="action-btn action--assign" data-id="${ticket.id}" title="Assign">👤</button>
         <button class="action-btn action--resolve" data-id="${ticket.id}" title="Mark resolved">✓</button>
       </div>`;

  return `
    <tr class="${rowClass}" data-id="${ticket.id}" tabindex="0" aria-label="Ticket ${ticket.id}: ${escHtml(ticket.subject)}">
      <td><div class="${rankClass}">${idx + 1}</div></td>
      <td><span class="ticket-id">${ticket.id}</span></td>
      <td>
        <div class="ticket-subject-wrap">
          <span class="ticket-subject">${escHtml(ticket.subject)}</span>
          <span class="ticket-company">${escHtml(ticket.company)}</span>
        </div>
      </td>
      <td>
        <div class="customer-cell">
          <span class="customer-name">${escHtml(ticket.customer)}</span>
          <span class="customer-company">${escHtml(ticket.email)}</span>
        </div>
      </td>
      <td><span class="priority-badge priority--${ticket.priority}">${cap(ticket.priority)}</span></td>
      <td><span class="status-badge status--${ticket.status}">${formatStatus(ticket.status)}</span></td>
      <td>${agentHtml}</td>
      <td>
        <div class="sla-cell">
          <span class="sla-timer sla--${statusClass}" id="sla-timer-${ticket.id}">
            ${isResolved ? 'Resolved' : formatCountdown(remaining)}
          </span>
          <div class="sla-bar-track">
            <div class="sla-bar-fill sla--${statusClass}" id="sla-bar-${ticket.id}" style="width:${barPct}%"></div>
          </div>
        </div>
      </td>
      <td>${actionsHtml}</td>
    </tr>
  `;
}

function escHtml(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function cap(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

