  const slaPreview = document.getElementById('sla-preview-val');

  function updateSlaPreview() {
    const config = getSlaConfig();
    const p = prioritySelect.value;
    const hours = config[p]?.hours ?? 24;
    slaPreview.textContent = `Response due within ${hours < 24 ? `${hours} hour${hours > 1 ? 's' : ''}` : `${hours / 24} day${hours > 24 ? 's' : ''}`}`;
  }

  prioritySelect?.addEventListener('change', updateSlaPreview);

  document.getElementById('modal-close-btn')?.addEventListener('click', closeModal);
  document.getElementById('modal-cancel-btn')?.addEventListener('click', closeModal);

  modal?.addEventListener('click', e => {
    if (e.target === modal) closeModal();
  });

  document.getElementById('modal-submit-btn')?.addEventListener('click', () => {
    const customer = document.getElementById('f-customer')?.value.trim();
    const subject  = document.getElementById('f-subject')?.value.trim();
    const email    = document.getElementById('f-email')?.value.trim();
    const company  = document.getElementById('f-company')?.value.trim();
    const priority = document.getElementById('f-priority')?.value;
    const assignee = document.getElementById('f-assignee')?.value || null;

    if (!customer) { alert('Customer name is required.'); return; }
    if (!subject)  { alert('Subject is required.'); return; }

    createTicket({ customer, email, company, subject, priority, assignee });
    showToast(`Ticket created for ${customer}`, 'success');
    closeModal();
    resetForm();
  });
}

export function openCreateModal() {
  const modal = document.getElementById('create-modal');
  if (modal) {
    modal.classList.remove('hidden');
    document.getElementById('f-customer')?.focus();
  }
}

function closeModal() {
  document.getElementById('create-modal')?.classList.add('hidden');
}

function resetForm() {
  ['f-customer','f-email','f-company','f-subject'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  const priority = document.getElementById('f-priority');
  if (priority) priority.value = 'normal';
  const assignee = document.getElementById('f-assignee');
  if (assignee) assignee.value = '';
}

/**
 * toast.js — Lightweight toast notification system.
 */

let _container = null;

export function initToast() {
  _container = document.createElement('div');
  _container.className = 'toast-container';
  _container.id = 'toast-container';
  document.body.appendChild(_container);
}

/**
 * @param {string} message
 * @param {'success'|'error'|'info'} type
 * @param {number} duration ms
 */
export function showToast(message, type = 'info', duration = 3500) {
  if (!_container) initToast();

  const icons = { success: '✅', error: '❌', info: 'ℹ️' };
  const toast = document.createElement('div');
  toast.className = `toast toast--${type}`;
  toast.innerHTML = `
    <span class="toast-icon">${icons[type] ?? 'ℹ️'}</span>
    <span class="toast-msg">${escHtml(message)}</span>
  `;
  _container.appendChild(toast);

  // Auto-remove after duration
  setTimeout(() => {
    toast.style.animation = 'toastOut 0.25s ease forwards';
    setTimeout(() => toast.remove(), 250);
  }, duration);
}

function escHtml(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/**
 * ticketDrawer.js — Sliding right-panel detail view for a single ticket.
 * Shows full info, SLA live timer, status transitions, assignment, and notes.
 */

import { slaStatusClass, timeRemaining } from '../engine/slaManager.js';
import { getSlaConfig } from '../engine/slaManager.js';
import { now } from '../engine/timeSimulator.js';
import { formatCountdown, formatDateTime, formatStatus, formatTimeAgo } from '../utils/formatters.js';
import { updateTicket, assignTicket, getTeam } from '../state/store.js';
import { showToast } from './toast.js';

let _currentTicketId = null;

export function initDrawer(container) {
  container.innerHTML = `
    <div class="drawer-overlay hidden" id="drawer-overlay"></div>
    <div class="drawer-panel hidden" id="drawer-panel" role="complementary" aria-label="Ticket details">
    </div>
  `;

  document.getElementById('drawer-overlay')?.addEventListener('click', closeDrawer);

  // Keyboard ESC closes drawer
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeDrawer();
  });
}

export function openDrawer(ticket) {
  _currentTicketId = ticket.id;
  document.getElementById('drawer-overlay')?.classList.remove('hidden');
  document.getElementById('drawer-panel')?.classList.remove('hidden');
  renderDrawerContent(ticket);
}

export function closeDrawer() {
  _currentTicketId = null;
  document.getElementById('drawer-overlay')?.classList.add('hidden');
  document.getElementById('drawer-panel')?.classList.add('hidden');
}

export function updateDrawerTimer(ticket) {
  if (!_currentTicketId || _currentTicketId !== ticket.id) return;
  const t = now();
  const remaining = timeRemaining(ticket, t);
  const statusClass = slaStatusClass(ticket, t);

  const timerEl = document.getElementById('drawer-sla-timer');
  const barEl = document.getElementById('drawer-sla-bar');

  if (timerEl) {
    timerEl.textContent = formatCountdown(remaining);
    timerEl.className = `sla-panel-timer sla--${statusClass}`;
  }

  if (barEl) {
    const config = getSlaConfig();
    const slaHours = config[ticket.priority]?.hours ?? 24;
    const totalMs = slaHours * 3600 * 1000;
    const elapsed = ticket.slaDeadline - ticket.createdAt - Math.max(remaining, 0);
    const pct = Math.min(100, Math.max(0, (elapsed / totalMs) * 100));
    barEl.style.width = `${pct}%`;
    barEl.className = `sla-panel-bar-fill sla--${statusClass}`;
  }
}

function renderDrawerContent(ticket) {
  const t = now();
  const remaining = timeRemaining(ticket, t);
  const statusClass = slaStatusClass(ticket, t);
  const team = getTeam();
  const agent = team.find(a => a.id === ticket.assignee);
  const isResolved = ['resolved', 'closed'].includes(ticket.status);

  const config = getSlaConfig();
  const slaHours = config[ticket.priority]?.hours ?? 24;
  const totalMs = slaHours * 3600 * 1000;
  const elapsed = isResolved ? totalMs : (ticket.slaDeadline - ticket.createdAt - Math.max(remaining, 0));
  const barPct = isResolved ? 100 : Math.min(100, Math.max(0, (elapsed / totalMs) * 100));

  const statusOptions = ['open', 'in_progress', 'waiting', 'resolved', 'closed'];

  const panel = document.getElementById('drawer-panel');
  panel.innerHTML = `
    <div class="drawer-header">
      <div class="drawer-header-left">
        <span class="drawer-ticket-id">${ticket.id}</span>
        <h3 class="drawer-subject">${escHtml(ticket.subject)}</h3>
        <div class="drawer-badges">
          <span class="priority-badge priority--${ticket.priority}">${cap(ticket.priority)}</span>
          <span class="status-badge status--${ticket.status}">${formatStatus(ticket.status)}</span>
        </div>
      </div>
      <button class="drawer-close" id="drawer-close-btn" aria-label="Close details">✕</button>
    </div>

    <div class="drawer-body">

      <!-- SLA Panel -->
      <div class="sla-panel">
        <div class="drawer-section-title">SLA Status</div>
        <div class="sla-panel-timer sla--${statusClass}" id="drawer-sla-timer">
          ${isResolved ? '✅ Resolved' : formatCountdown(remaining)}
        </div>
        <div class="sla-panel-bar-track">
          <div class="sla-panel-bar-fill sla--${statusClass}" id="drawer-sla-bar" style="width:${barPct}%"></div>
        </div>
        <div class="sla-panel-meta">
          <span>Opened: ${formatTimeAgo(ticket.createdAt)}</span>
          <span>Deadline: ${formatDateTime(ticket.slaDeadline)}</span>
        </div>
      </div>

      <!-- Customer Info -->
      <div>
        <div class="drawer-section-title">Customer</div>
        <div class="drawer-info-grid">
          <div class="drawer-info-item">
            <div class="drawer-info-label">Name</div>
            <div class="drawer-info-value">${escHtml(ticket.customer)}</div>
          </div>
          <div class="drawer-info-item">
            <div class="drawer-info-label">Company</div>
            <div class="drawer-info-value">${escHtml(ticket.company || '—')}</div>
          </div>
          <div class="drawer-info-item">
            <div class="drawer-info-label">Email</div>
            <div class="drawer-info-value">${escHtml(ticket.email || '—')}</div>
          </div>
          <div class="drawer-info-item">
            <div class="drawer-info-label">Opened</div>
            <div class="drawer-info-value">${formatDateTime(ticket.createdAt)}</div>
          </div>
        </div>
      </div>

      <!-- Assignment -->
      <div>
        <div class="drawer-section-title">Assignee</div>
        <div class="assign-row">
          <select class="form-select" id="drawer-assign-select" style="max-width:200px;">
            <option value="">Unassigned</option>
            ${team.map(a => `<option value="${a.id}" ${ticket.assignee === a.id ? 'selected' : ''}>${a.name}</option>`).join('')}
          </select>
          <button class="btn btn--ghost btn--sm" id="drawer-assign-btn">Save</button>
        </div>
      </div>

      <!-- Status Transition -->
      ${!isResolved ? `
      <div>
        <div class="drawer-section-title">Change Status</div>
        <div class="status-actions">
          ${statusOptions.filter(s => s !== ticket.status).map(s => `
            <button class="btn btn--ghost btn--sm drawer-status-btn" data-status="${s}">
              → ${formatStatus(s)}
            </button>
          `).join('')}
        </div>
      </div>
      ` : ''}

      <!-- Notes -->
      <div>
        <div class="drawer-section-title">Notes</div>
        <textarea class="notes-area" id="drawer-notes" placeholder="Add notes, workarounds, or updates…">${escHtml(ticket.note ?? '')}</textarea>
        <div style="margin-top:8px;">
          <button class="btn btn--ghost btn--sm" id="drawer-save-note-btn">Save Note</button>
        </div>
      </div>

      <!-- History -->
      ${ticket.history?.length ? `
      <div>
        <div class="drawer-section-title">History</div>
        <div class="history-list">
          ${(ticket.history ?? []).map(h => `
            <div class="history-item">
              <span class="history-dot"></span>
              <span>${escHtml(h.msg)} — <em>${formatDateTime(h.at)}</em></span>
            </div>
          `).join('')}
        </div>
      </div>
      ` : ''}

    </div>
  `;

  // Events
  document.getElementById('drawer-close-btn')?.addEventListener('click', closeDrawer);

  document.getElementById('drawer-assign-btn')?.addEventListener('click', () => {
    const agentId = document.getElementById('drawer-assign-select')?.value || null;
    assignTicket(ticket.id, agentId);
    const name = team.find(a => a.id === agentId)?.name ?? 'Unassigned';
    showToast(`Assigned to ${name}`, 'success');
  });

  document.querySelectorAll('.drawer-status-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const newStatus = btn.dataset.status;
      updateTicket(ticket.id, { status: newStatus });
      showToast(`Status updated to ${formatStatus(newStatus)}`, 'success');
      closeDrawer();
    });
  });

  document.getElementById('drawer-save-note-btn')?.addEventListener('click', () => {
    const note = document.getElementById('drawer-notes')?.value ?? '';
    updateTicket(ticket.id, { note });
    showToast('Note saved', 'success');
  });
}

function escHtml(str) {
  return String(str ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function cap(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

/**
 * main.js — Application bootstrap.
 * Wires together the store, queue engine, time simulator, and all UI components.
 */

import '../src/styles/reset.css';
import '../src/styles/variables.css';
import '../src/styles/animations.css';
import '../src/styles/queue.css';
import '../src/styles/components.css';

import { init as initStore, getTickets, getActiveAgent, setActiveAgent, updateTicket, assignTicket, getAgentById, getTeam, subscribe as storeSubscribe } from './src/state/store.js';
import { sortQueue } from './src/engine/queueEngine.js';
import { subscribe as clockSubscribe, now, advanceTime, resetTime, formatOffset } from './src/engine/timeSimulator.js';
import { renderQueueHeader, updateQueueHeader } from './src/components/queueHeader.js';
import { renderPickNextBanner, updatePickNextTimer } from './src/components/pickNextBanner.js';
import { renderFilterBar, applyFilters, getFilters } from './src/components/filterBar.js';
import { renderTicketList, updateTicketTimers } from './src/components/ticketList.js';
import { renderPagination, paginateTickets, totalPages, setPage, getPage } from './src/components/pagination.js';
import { initDrawer, openDrawer, closeDrawer, updateDrawerTimer } from './src/components/ticketDrawer.js';
import { renderTicketModal, openCreateModal } from './src/components/ticketModal.js';
import { initToast, showToast } from './src/components/toast.js';
import { formatStatus } from './src/utils/formatters.js';

// ── DOM refs ───────────────────────────────────────────────────────────────────
const $header       = document.getElementById('app-header');
const $statsBanner  = document.getElementById('stats-banner');
const $simBar       = document.getElementById('sim-bar');
const $pickNext     = document.getElementById('pick-next');
const $filterBar    = document.getElementById('filter-bar');
const $filterSummary = document.getElementById('filter-summary');
const $queueWrap    = document.getElementById('queue-wrap');
const $queueContent = document.getElementById('queue-content');
const $pagination   = document.getElementById('pagination');
const $drawerMount  = document.getElementById('drawer-mount');
const $modalMount   = document.getElementById('modal-mount');

// ── Live clock tick state ───────────────────────────────────────────────────
let _lastFullRenderTime = 0;
const FULL_RENDER_INTERVAL_MS = 3000; // Full re-render + re-sort every 3 seconds
let _currentFiltered = [];

// ── Bootstrap ───────────────────────────────────────────────────────────────
initStore();
initToast();
initDrawer($drawerMount);
renderTicketModal($modalMount);
renderAppHeader();
renderSimBar();
fullRender();

// ── Store subscription — re-render when tickets change ──────────────────────
storeSubscribe(() => {
  fullRender();
});

// ── Clock subscription — tick-based timer updates ────────────────────────────
clockSubscribe((t) => {
  const timeSinceFull = t - _lastFullRenderTime;
  if (timeSinceFull >= FULL_RENDER_INTERVAL_MS) {
    fullRender();
  } else {
    // Lightweight timer-only update every second
    updateQueueHeader(getTickets());
    updatePickNextTimer(getTickets());
    updateTicketTimers(_currentFiltered);
    // update drawer if open
    const tickets = getTickets();
    tickets.forEach(tk => updateDrawerTimer(tk));
  }
  // Always update the sim bar offset display
  const offsetEl = document.getElementById('sim-offset-display');
  if (offsetEl) offsetEl.textContent = formatOffset();
  // Update live clock
  const clockEl = document.getElementById('live-clock');
  if (clockEl) {
    const d = new Date(now());
    clockEl.textContent = d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
  }
});

// ── Full render cycle ───────────────────────────────────────────────────────
function fullRender() {
  _lastFullRenderTime = now();
  const tickets = getTickets();
  const agentId = getActiveAgent();
  const filters = getFilters();

  // 1. Sort by queue engine
  const sorted = sortQueue(tickets, now());

  // 2. Apply UI filters
  const filtered = applyFilters(sorted, filters, agentId);
  _currentFiltered = filtered;

  // 3. Paginate
  const page = getPage();
  const pages = totalPages(filtered.length);
  if (page > pages) setPage(Math.max(1, pages));
  const visible = paginateTickets(filtered);

  // 4. Render components
  renderQueueHeader(tickets, $statsBanner);
  renderPickNextBanner(tickets, $pickNext, {
    onPick: (ticket) => handlePickNext(ticket),
    onView: (ticket) => openDrawer(ticket),
  });
  renderFilterBar($filterBar, {
    onChange: () => {
      setPage(1);
      fullRender();
    },
    activeAgentId: agentId,
    allTickets: tickets,
  });
  renderFilterSummary(filtered.length, sorted.length, filters);
  renderTicketList(visible, $queueContent, {
    onView:    (ticket) => openDrawer(ticket),
    onAssign:  (ticket) => handleQuickAssign(ticket),
    onResolve: (ticket) => handleResolve(ticket),
    onStatusChange: (ticket, status) => updateTicket(ticket.id, { status }),
  });
  renderPagination($pagination, {
    total: filtered.length,
    onChange: () => fullRender(),
  });
}

// ── Filter summary row ──────────────────────────────────────────────────────
function renderFilterSummary(filteredCount, totalCount, filters) {
  const activeFilters = [
    filters.tab !== 'all' ? `Tab: ${filters.tab}` : null,
    filters.priority !== 'all' ? `Priority: ${filters.priority}` : null,
    filters.status !== 'active' ? `Status: ${filters.status}` : null,
    filters.search ? `Search: "${filters.search}"` : null,
  ].filter(Boolean);

  $filterSummary.innerHTML = `
    <div class="filter-summary">
      <span class="filter-count">${filteredCount} ticket${filteredCount !== 1 ? 's' : ''}</span>
      ${activeFilters.length ? `<span style="color:var(--text-muted);font-size:11px;">${activeFilters.join(' · ')}</span>` : ''}
      ${activeFilters.length ? `<button class="btn btn--ghost btn--sm" id="clear-filters-btn" style="font-size:11px;padding:2px 8px;">Clear filters</button>` : ''}
    </div>
  `;

  document.getElementById('clear-filters-btn')?.addEventListener('click', () => {
    // Reset filters to defaults
    import('./src/components/filterBar.js').then(({ getFilters }) => {
      const f = getFilters();
      Object.assign(f, { search: '', tab: 'all', priority: 'all', status: 'active' });
      setPage(1);
      fullRender();
    });
  });
}

// ── App Header ────────────────────────────────────────────────────────────────
function renderAppHeader() {
  const team = getTeam();
  $header.innerHTML = `
    <header class="app-header">
      <div class="header-brand">
        <div class="brand-logo">🎫</div>
        <div>
          <div class="brand-title">HelpQueue Pro</div>
          <div class="brand-subtitle">Smart SLA-Driven IT Helpdesk</div>
        </div>
      </div>
      <div class="header-right">
        <div class="live-clock">
          <span style="color:var(--text-muted);font-size:11px;">TIME </span>
          <span class="clock-time" id="live-clock">—</span>
        </div>
        <div class="agent-switcher" id="agent-switcher">
          ${team.map(agent => `
            <button
              class="agent-switcher-btn ${getActiveAgent() === agent.id ? 'active' : ''}"
              data-agent="${agent.id}"
              id="agent-btn-${agent.id}"
              aria-label="Switch to ${agent.name}"
            >
              <div class="agent-avatar" style="background:${agent.color}22;color:${agent.color};width:22px;height:22px;font-size:9px;">${agent.avatar}</div>
              ${agent.name.split(' ')[0]}
            </button>
          `).join('')}
        </div>
        <button class="btn btn--primary" id="new-ticket-btn" aria-label="Create new ticket">
          + New Ticket
        </button>
      </div>
    </header>
  `;

  document.getElementById('new-ticket-btn')?.addEventListener('click', openCreateModal);

  document.querySelectorAll('[data-agent]').forEach(btn => {
    btn.addEventListener('click', () => {
      setActiveAgent(btn.dataset.agent);
      renderAppHeader(); // refresh active state
    });
  });
}

// ── Simulator Bar ─────────────────────────────────────────────────────────────
function renderSimBar() {
  $simBar.innerHTML = `
    <div class="sim-bar" title="Time-warp simulator: advance clock to see SLA breaches live">
      <span class="sim-bar-label">⚗️ SLA Simulator</span>
      <span class="sim-offset" id="sim-offset-display">${formatOffset()}</span>
      <button class="sim-btn" id="sim-plus-30" title="Advance time by 30 minutes">+30m</button>
      <button class="sim-btn" id="sim-plus-1h" title="Advance time by 1 hour">+1h</button>
      <button class="sim-btn" id="sim-plus-2h" title="Advance time by 2 hours">+2h</button>
      <button class="sim-btn" id="sim-plus-4h" title="Advance time by 4 hours">+4h</button>
      <button class="sim-btn sim-btn--reset" id="sim-reset" title="Reset to real time">↩ Reset</button>
      <span style="color:var(--text-muted);font-size:11px;margin-left:4px;">Watch tickets breach SLA and jump to the front!</span>
    </div>
  `;

  document.getElementById('sim-plus-30')?.addEventListener('click', () => { advanceTime(30 * 60 * 1000); fullRender(); });
  document.getElementById('sim-plus-1h')?.addEventListener('click', () => { advanceTime(60 * 60 * 1000); fullRender(); });
  document.getElementById('sim-plus-2h')?.addEventListener('click', () => { advanceTime(2 * 60 * 60 * 1000); fullRender(); });
  document.getElementById('sim-plus-4h')?.addEventListener('click', () => { advanceTime(4 * 60 * 60 * 1000); fullRender(); });
  document.getElementById('sim-reset')?.addEventListener('click', () => { resetTime(); fullRender(); });
}

// ── Action Handlers ─────────────────────────────────────────────────────────
function handlePickNext(ticket) {
  const agentId = getActiveAgent();
  const agent = getAgentById(agentId);
  if (ticket.assignee !== agentId) {
    assignTicket(ticket.id, agentId);
  }
  if (ticket.status === 'open') {
    updateTicket(ticket.id, { status: 'in_progress' });
  }
  showToast(`Picked up ${ticket.id} — now in progress`, 'success');
  openDrawer({ ...ticket, assignee: agentId, status: 'in_progress' });
}

function handleQuickAssign(ticket) {
  const agentId = getActiveAgent();
  const agent = getAgentById(agentId);
  assignTicket(ticket.id, agentId);
  showToast(`Assigned ${ticket.id} to ${agent?.name ?? 'you'}`, 'success');
}

function handleResolve(ticket) {
  if (confirm(`Mark "${ticket.subject.slice(0, 50)}…" as resolved?`)) {
    updateTicket(ticket.id, { status: 'resolved' });
    showToast(`${ticket.id} resolved ✅`, 'success');
  }
}

